void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // 画面の座標を正規化
    vec2 uv = fragCoord/iResolution.xy;

    // アスペクト比の調整
    uv.x *= iResolution.x/iResolution.y;

    // 中心を(0,0)にする
    vec2 center = uv - vec2(iResolution.x/iResolution.y * 0.5, 0.5);

    // ゆっくりとした時間の流れ
    float slowTime = iTime * 0.3;

    // 複数の波を重ねる
    float wave1 = sin(length(center) * 8.0 - slowTime) * 0.5 + 0.5;
    float wave2 = sin(length(center) * 5.0 - slowTime * 0.7) * 0.5 + 0.5;
    float wave3 = sin(length(center) * 3.0 - slowTime * 0.5) * 0.5 + 0.5;

    // 波を組み合わせる
    float waves = (wave1 + wave2 + wave3) / 3.0;

    // パステルカラーの基本色
    vec3 baseColor1 = vec3(0.7, 0.9, 1.0);  // 薄い水色
    vec3 baseColor2 = vec3(0.9, 0.8, 1.0);  // 薄い紫
    vec3 baseColor3 = vec3(0.8, 1.0, 0.9);  // 薄い緑

    // 色を時間とともにゆっくり変化させる
    float colorMix1 = sin(slowTime * 0.5) * 0.5 + 0.5;
    float colorMix2 = cos(slowTime * 0.3) * 0.5 + 0.5;

    // 最終的な色を計算
    vec3 finalColor = mix(
        mix(baseColor1, baseColor2, colorMix1),
        baseColor3,
        colorMix2
    );

    // 波の効果を加える
    finalColor = mix(
        finalColor,
        finalColor * (0.8 + waves * 0.4),
        0.8
    );

    // ビネット効果（画面端を少し暗く）
    float vignette = 1.0 - length(center) * 0.5;
    finalColor *= vignette;

    // 最終出力
    fragColor = vec4(finalColor, 1.0);
}
